**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int px[100], py[100];
    for (int i = 0; i < n; i++) plik >> px[i] >> py[i];
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double dx = px[j] - px[i];
            double dy = py[j] - py[i];
            double dl = sqrt(dx * dx + dy * dy);
            double sx = (px[i] + px[j]) / 2.0;
            double sy = (py[i] + py[j]) / 2.0;
            cout << "(" << px[i] << "," << py[i] << ")-(" << px[j] << "," << py[j] << "): "
                 << "dlugosc = " << dl << ", srodek = (" << sx << ", " << sy << ")" << endl;
        }
    }
    return 0;
}
```

**Wyjasnienie**: Podwojna petla z i < j generuje kazda pare dokladnie raz. Dlugosc odcinka to odleglosc euklidesowa, srodek to srednia wspolrzednych.

